/// host thread stays live. The real backend (netfetcher for http(s), errand for
/// smolweb) is supplied by the content actor when it wires `net`. Linked only under
/// the `net` grant, and gated here to the instance's origin allowlist (§E1): `net`
/// means "may reach these origins", so a cross-origin URL is refused before the
/// backend runs (closes the credentialed-SSRF / cross-origin-exfil channel).
impl crate::mere::script::net::Host for ScriptHost {
    async fn fetch(
        &mut self,
        req: crate::mere::script::net::Request,
    ) -> Result<crate::mere::script::net::Response, String> {
        // Per-turn rate cap first (§A6): bound how many fetches one turn can issue, so
        // a granted script cannot flood egress in a loop. Reset each turn.
        if self.fetches_this_turn >= self.max_fetches_per_turn {
            return Err(format!(
                "net.fetch: per-turn request limit reached ({})",
                self.max_fetches_per_turn
            ));
        }
        self.fetches_this_turn += 1;
        // Origin gate: the script may only reach its granted origins (default
        // same-origin), so a granted `net` cannot exfiltrate to or read an arbitrary
        // third-party host. Enforced before the backend is even consulted.
        if !host_in_origins(&req.url, &self.net_origins) {
            return Err(format!(
                "net.fetch: {} is outside this script's net origins",
                req.url
            ));
        }
        // Call the injected backend (netfetcher/errand, supplied by the content actor).
        // Blocking on the turn's fiber: the host thread parks for the I/O, then the
        // fiber resumes with the result. No backend configured = an error to the guest.
        let fetcher = self
            .fetcher
            .as_ref()
            .ok_or_else(|| "net backend not configured".to_string())?;
        let resp = fetcher.fetch(&req.url)?;
        Ok(crate::mere::script::net::Response {
            status: resp.status,
            content_type: resp.content_type,
            body: resp.body,
        })
    }
}

/// Apply a batch atomically against the host-side `revision`. Every referenced id
/// is checked live before mutating (unknown-node, nothing applied); an empty batch
/// is a no-op that does not advance the revision. Returns the new (or unchanged)
/// revision.
pub fn apply(
    dom: &mut ScriptedDom,
    revision: &mut u64,
    batch: ApplyBatch,
) -> Result<u64, TurnError> {
    if batch.expected_revision != *revision {
        return Err(TurnError::RevisionConflict(*revision));
    }
    for m in &batch.changes {
        let referenced = match m {
            Mutation::SetText(a) => Some(a.node),
            Mutation::Remove(id) => Some(*id),
            Mutation::InsertBefore(a) => Some(a.reference),
            Mutation::AppendChild(a) => Some(a.parent),
        };
        if let Some(raw) = referenced {
            if !dom.is_live(NodeId::from_raw(raw as u64)) {
                return Err(TurnError::UnknownNode(raw));
            }
        }
    }
    if batch.changes.is_empty() {
        return Ok(*revision);
    }
    for m in batch.changes {
        apply_one(dom, m);
    }
    *revision += 1;
    Ok(*revision)
}

fn apply_one(dom: &mut ScriptedDom, m: Mutation) {
    match m {
        Mutation::SetText(SetTextArgs { node, text }) => {
            dom.set_text(NodeId::from_raw(node as u64), &text);
        },
        Mutation::Remove(id) => {
            dom.remove(NodeId::from_raw(id as u64));
        },
        Mutation::InsertBefore(InsertArgs { reference, new }) => {
            let reference = NodeId::from_raw(reference as u64);
            if let Some(parent) = dom.parent(reference) {
                let child = create_block(dom, new);
                dom.insert_before(parent, child, Some(reference));
            }
        },
        Mutation::AppendChild(AppendArgs { parent, new }) => {
            let parent = NodeId::from_raw(parent as u64);
            let child = create_block(dom, new);
            dom.append_child(parent, child);
        },
    }
}

/// A block becomes one DOM node: `#text` → a text node; otherwise an element named
/// by `kind` (element text content is a separate `#text` block).
fn create_block(dom: &mut ScriptedDom, block: Block) -> NodeId {
    if block.kind == "#text" {
        dom.create_text(&block.text)
    } else {
        dom.create_element(qual(&block.kind))
    }
}

