/// [`Config::epoch_interruption()`](crate::Config::epoch_interruption)
/// for an introduction to epoch-based interruption.
#[cfg(target_has_atomic = "64")]
pub fn set_epoch_deadline(&mut self, ticks_beyond_current: u64) {
